# The data structure: a dictionary of name -> list of scores
students = {}

def add_student(name, score):
    if name not in students:
        students[name] = []        # start a new list for this student
    students[name].append(score)

def get_average(scores):
    if len(scores) == 0:
        return 0
    return sum(scores) / len(scores)

def get_grade(average):
    if average >= 90: return "A"
    elif average >= 80: return "B"
    elif average >= 70: return "C"
    elif average >= 60: return "D"
    else: return "F"

def show_all():
    if len(students) == 0:
        print("No students yet.")
        return

    print("\n--- All Students ---")
    for name, scores in students.items():
        avg = get_average(scores)
        grade = get_grade(avg)
        print(f"{name:15} Avg: {avg:.1f}  Grade: {grade}")

def show_top_student():
    if len(students) == 0:
        print("No students yet.")
        return

    top_name = None
    top_avg = -1
    for name, scores in students.items():
        avg = get_average(scores)
        if avg > top_avg:
            top_avg = avg
            top_name = name
    print(f"\nTop student: {top_name} with average {top_avg:.1f}")

def main_menu():
    while True:
        print("\n=== Grade Tracker ===")
        print("1. Add student score")
        print("2. Show all students")
        print("3. Show top student")
        print("4. Search student")
        print("5. Quit")

        choice = input("Choose: ")

        if choice == "1":
            name  = input("Student name: ").strip().title()
            score = float(input("Score (0-100): "))
            add_student(name, score)
            print(f"Added {name}: {score}")
        elif choice == "2":
            show_all()
        elif choice == "3":
            show_top_student()
        elif choice == "4":
            name = input("Search name: ").strip().title()
            if name in students:
                scores = students[name]
                avg = get_average(scores)
                print(f"{name}: scores={scores}, avg={avg:.1f}, grade={get_grade(avg)}")
            else:
                print(f"{name} not found.")
        elif choice == "5":
            print("Goodbye!")
            break
        else:
            print("Invalid choice.")

main_menu()

