students = {}

def add_student(name, score):
    if name not in students:
        students[name] = []
    students[name].append(score)

def get_average(scores):
    if len(scores) == 0:
        return 0
    return sum(scores) / len(scores)

def get_grade(average):
    if average >= 90: return "A"
    elif average >= 80: return "B"
    elif average >= 70: return "C"
    elif average >= 60: return "D"
    else: return "F"

def show_all():
    if len(students) == 0:
        print("No students yet."); return
    for name, scores in students.items():
        avg = get_average(scores)
        print(f"{name}: {avg:.1f} ({get_grade(avg)})")

def show_class_average():
    all_scores = []
    for scores in students.values():
        all_scores.extend(scores)
    if len(all_scores) == 0:
        print("No scores yet."); return
    print(f"Class average: {get_average(all_scores):.1f}")

while True:
    print("\n1.Add  2.Show all  3.Class avg  4.Quit")
    c = input("Choose: ")
    if c == "1":
        n = input("Name: ").strip().title()
        s = float(input("Score: "))
        add_student(n, s); print("Added.")
    elif c == "2": show_all()
    elif c == "3": show_class_average()
    elif c == "4": print("Goodbye!"); break
    else: print("Invalid.")
